using Godot;
using Drycastle.Shooter.Audio;
using Drycastle.Shooter.Effects;
using Drycastle.Shooter.Weapons;

namespace Drycastle.Shooter.Thieves;

/// <summary>
/// The electrocution of a Thief at the top of a pole (docs/events/thieves/07), client only: jagged electric beams from the man to the wire seats of the pole for the shock's seconds, a shower of sparks,
/// a flickering blue light and the crackle sound (<see cref="Sound"/>, generated by <c>scripts/sounds/make_shock_crackle.py</c>, heard to 40 m). One <see cref="Beams"/> node per shock, freed when it ends. Beams are
/// camera-facing ribbons (a line is one pixel wide), redrawn with new jags about twenty times a second. Skipped on headless runs and when the camera is far away.
/// </summary>
public static partial class ShockFx
{
    /// <summary>The sound's id in sounds.json.</summary>
    public const string Sound = "shock.crackle";

    /// <summary>Beams are built within this of the camera (about as far as the sound is heard, with room for the light).</summary>
    const float SeeM = 80f;
    const int MaxBeams = 8;

    /// <summary>Starts the effect: <paramref name="origin"/> is where the beams start (the man's chest, asked every frame), <paramref name="seats"/> the wire seats they strike, for <paramref name="seconds"/>.</summary>
    public static void Play(Node3D world, Func<Vector3> origin, IReadOnlyList<Vector3> seats, float seconds)
    {
        if (!ShotFx.Enabled || !GodotObject.IsInstanceValid(world) || !world.IsInsideTree()) return;
        var at = origin();
        if (Sfx.Enabled) Sfx.Play3D(Sound, at);
        if (Sfx.ListenerDistance(at) > SeeM) return;
        var near = seats.OrderBy(s => s.DistanceSquaredTo(at)).Take(MaxBeams).ToArray();
        var beams = new Beams(origin, near, seconds) { Name = "ShockBeams" };
        world.AddChild(beams);
    }

    sealed partial class Beams : Node3D
    {
        const float Hz = 20f, WidthM = 0.045f, JagM = 0.16f, Segments = 7;

        static StandardMaterial3D? _beamMat, _sparkMat;
        static SphereMesh? _sparkMesh;

        readonly Func<Vector3> _origin;
        readonly Vector3[] _seats;
        readonly float _seconds;
        readonly Random _rng = new();
        readonly MeshInstance3D _mesh = new() { CastShadow = GeometryInstance3D.ShadowCastingSetting.Off };
        readonly ImmediateMesh _im = new();
        readonly CpuParticles3D _sparks;
        readonly OmniLight3D _light = new() { LightColor = new Color(0.55f, 0.75f, 1f), OmniRange = 7f, ShadowEnabled = false };
        float _age, _redraw;

        public Beams(Func<Vector3> origin, Vector3[] seats, float seconds)
        {
            _origin = origin; _seats = seats; _seconds = seconds;
            _beamMat ??= new StandardMaterial3D
            {
                ShadingMode = BaseMaterial3D.ShadingModeEnum.Unshaded, AlbedoColor = new Color(0.8f, 0.9f, 1f), CullMode = BaseMaterial3D.CullModeEnum.Disabled,
                EmissionEnabled = true, Emission = new Color(0.55f, 0.75f, 1f), EmissionEnergyMultiplier = 3f,
            };
            _sparkMat ??= new StandardMaterial3D
            {
                ShadingMode = BaseMaterial3D.ShadingModeEnum.Unshaded, AlbedoColor = new Color(0.8f, 0.9f, 1f),
                EmissionEnabled = true, Emission = new Color(0.6f, 0.8f, 1f), EmissionEnergyMultiplier = 3f,
            };
            _sparkMesh ??= new SphereMesh { Radius = 0.02f, Height = 0.04f, RadialSegments = 6, Rings = 3, Material = _sparkMat };
            _mesh.Mesh = _im;
            _mesh.MaterialOverride = _beamMat;
            _mesh.ExtraCullMargin = 50f;
            AddChild(_mesh);
            _sparks = new CpuParticles3D
            {
                Visible = false, Emitting = false, Mesh = _sparkMesh, Amount = 36, Lifetime = 0.45, Explosiveness = 0f, Spread = 180f, InitialVelocityMin = 1.5f, InitialVelocityMax = 4.5f,
                Gravity = new Vector3(0, -9f, 0), LocalCoords = false, CastShadow = GeometryInstance3D.ShadowCastingSetting.Off,
            };
            AddChild(_sparks);
            AddChild(_light);
        }

        public override void _Ready() { ParticleFx.Run(_sparks, true); }

        public override void _Process(double delta)
        {
            _age += (float)delta;
            if (_age >= _seconds) { QueueFree(); return; }
            var from = _origin();
            _sparks.GlobalPosition = from;
            _light.GlobalPosition = from;
            _light.LightEnergy = 1.5f + (float)_rng.NextDouble() * 3f; // flickers
            _redraw -= (float)delta;
            if (_redraw > 0) return;
            _redraw = 1f / Hz;
            Draw(from);
        }

        void Draw(Vector3 from)
        {
            _im.ClearSurfaces();
            if (_seats.Length == 0) return;
            var cam = GetViewport().GetCamera3D();
            var eye = cam != null ? cam.GlobalPosition : from + Vector3.Up * 5f;
            _im.SurfaceBegin(Mesh.PrimitiveType.Triangles);
            foreach (var seat in _seats)
            {
                if (_rng.NextDouble() < 0.2) continue; // a beam now and then drops out: the flicker
                var prev = from;
                for (var i = 1; i <= (int)Segments; i++)
                {
                    var t = i / Segments;
                    var p = from.Lerp(seat, t);
                    if (i < (int)Segments) p += new Vector3(Jag(), Jag(), Jag()) * Mathf.Sin(t * Mathf.Pi);
                    Quad(prev, p, eye);
                    prev = p;
                }
            }
            _im.SurfaceEnd();
        }

        float Jag() => ((float)_rng.NextDouble() * 2f - 1f) * JagM;

        void Quad(Vector3 a, Vector3 b, Vector3 eye)
        {
            var dir = b - a;
            if (dir.LengthSquared() < 1e-6f) return;
            var side = dir.Cross(eye - (a + b) * 0.5f);
            if (side.LengthSquared() < 1e-9f) return;
            side = side.Normalized() * (WidthM * 0.5f);
            _im.SurfaceAddVertex(a - side); _im.SurfaceAddVertex(a + side); _im.SurfaceAddVertex(b + side);
            _im.SurfaceAddVertex(a - side); _im.SurfaceAddVertex(b + side); _im.SurfaceAddVertex(b - side);
        }
    }
}
